using System.Text.Json;
using Cortex.Video.Composition;
using Cortex.Video.Editing;
using Xunit;
namespace Cortex.Video.Tests;
public sealed class HelengineCompositionCompilerTests {
    [Fact] public void V1ZoomCompilesToSmoothstepV1() {var script=HelengineCompositionTestData.Script();var plan=EditorialDecisionContext.Inherit(script);plan=plan with{Scenes=[plan.Scenes[0] with{Proposal=plan.Scenes[0].Proposal with{Motion=new(){Type="zoom",StartSec=.5,DurationSec=1,FromScale=1,ToScale=1.35,Easing="ease_in_out"}}},plan.Scenes[1]]};var result=HelengineCompositionCompiler.CompilePlanning(script,plan,HelengineCompositionTestData.Bindings(),HelengineCompositionTestData.Catalog(),32,32);Assert.True(result.IsExecutable);var animations=result.Composition.GetProperty("layers").EnumerateArray().SelectMany(layer=>layer.GetProperty("animations").EnumerateArray()).ToArray();Assert.Contains(animations,track=>track.GetProperty("property").GetString()=="zoom" && track.GetProperty("keyframes")[0].GetProperty("curve").GetString()=="smoothstep.v1");Assert.Equal(EditingDocumentKinds.Decisions,plan.Schema);}
    [Fact] public void PendingFocusIsNotInvented() {var original=HelengineCompositionTestData.Script();var script=original with{Beats=[original.Beats[0] with{Visual=original.Beats[0].Visual with{Focus=new(){Type="text_region",TargetText="texto"}}},original.Beats[1]]};var plan=EditorialDecisionContext.Inherit(script);plan=plan with{Scenes=[plan.Scenes[0] with{Proposal=plan.Scenes[0].Proposal with{Motion=new(){Type="zoom",Focus=new("text_region","texto")}}},plan.Scenes[1]]};var result=HelengineCompositionCompiler.CompilePlanning(script,plan,HelengineCompositionTestData.Bindings(),HelengineCompositionTestData.Catalog(),32,32);Assert.False(result.IsExecutable);Assert.Contains(result.Pending,item=>item.Code=="focus_unresolved");Assert.DoesNotContain(result.Composition.GetProperty("layers").EnumerateArray().SelectMany(layer=>layer.GetProperty("animations").EnumerateArray()),track=>track.GetProperty("property").GetString()=="zoom");}
    [Fact] public void ResolvedSpeechTimingRequiredForFinal() {var original=HelengineCompositionTestData.Script();var script=original with{Beats=[original.Beats[0] with{Audio=new(){Type=AudioKind.Record,Script="fala real"}},original.Beats[1]]};var plan=EditorialDecisionContext.Inherit(script);Assert.Throws<InvalidDataException>(()=>HelengineCompositionCompiler.Compile(script,plan,HelengineCompositionTestData.Resolved(script),HelengineCompositionTestData.Catalog()));}
    [Fact] public async Task GeneratedDocumentPassesEngineValidation() {var script=HelengineCompositionTestData.Script();var image=HelengineCompositionTestData.Image() with{Sha256=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes("C:/dev/helworks/builds/helengine/media-composition/fixtures/gpu-red.png")))};var resolved=HelengineCompositionTestData.Resolved(script) with{Media=[image]};var result=HelengineCompositionCompiler.Compile(script,EditorialDecisionContext.Inherit(script),resolved,HelengineCompositionTestData.Catalog());var client=new HelengineCompositionClient("C:/dev/helworks/builds/helengine/media-composition/worktrees/helengine/engine/helengine.vfx.cli/bin/Debug/net9.0/helengine.vfx.cli.dll","C:/env/ffmpeg-8.1.1-full_build-shared/bin/ffmpeg.exe");await client.ValidateAsync(result.Composition,"C:/dev/helworks/builds/helengine/media-composition/fixtures",CancellationToken.None);}
    [Fact] public void RawFileFingerprintUsesTheCurrentLoadedReference() {var script=HelengineCompositionTestData.Script();var plan=EditorialDecisionContext.Inherit(script);string raw=EditingJson.Serialize(script).GetRawText()+"\n";var current=new EditingDocumentReference{Path="script.json",Revision=script.Revision,Sha256=Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(raw)))};var resolved=HelengineCompositionTestData.Resolved(script) with{ScriptRef=current};var result=HelengineCompositionCompiler.Compile(script,plan,resolved,HelengineCompositionTestData.Catalog(),current);Assert.True(result.IsExecutable);Assert.Throws<InvalidDataException>(()=>HelengineCompositionCompiler.Compile(script,plan,resolved,HelengineCompositionTestData.Catalog(),current with{Sha256=new string('e',64)}));}
}
